import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';

// src/styles/gensen-faces.css (generated by scripts/subset-fonts.py) splits
// each GenSen Rounded TW weight into a full file (~280 KB), a "page" layer
// (what the homepage renders in that weight) and a preloaded "hero" layer.
// The homepage should never need the full files.
const root = path.resolve(__dirname, '..');
const css = fs.readFileSync(path.join(root, 'src/styles/gensen-faces.css'), 'utf8');
const faces = [...css.matchAll(/@font-face \{([\s\S]*?)\n\}/g)].map(([, body]) => ({
  file: body.match(/GenSenRounded2TW-(\w+?)(-page|-hero)?\.woff2/)!,
  weight: Number(body.match(/font-weight: (\d+)/)![1]),
  range: body.match(/unicode-range: ([^;]+);/)?.[1],
}));

function inRange(range: string, cp: number) {
  return range.split(',').some(part => {
    const [a, b = a] = part.trim().replace(/^U\+/, '').split('-');
    return cp >= parseInt(a, 16) && cp <= parseInt(b, 16);
  });
}

describe('GenSen font faces', () => {
  // Regression: the full files had no unicode-range, i.e. claimed every
  // character. A character the font lacks (· → ↗ 徹 on the homepage) made
  // the browser download the whole ~280 KB file before falling back to
  // Noto Sans TC — the R and M full files loaded on every visit.
  it('every face, the full files included, claims only a unicode-range', () => {
    expect(faces.length).toBeGreaterThanOrEqual(12);
    for (const f of faces) expect(f.range, f.file[0]).toBeTruthy();
  });

  it('each weight declares its full file first and smaller layers after (later faces win), all present on disk', () => {
    const byWeight = new Map<number, string[]>();
    for (const f of faces) {
      byWeight.set(f.weight, [...(byWeight.get(f.weight) ?? []), f.file[2] ?? 'full']);
      expect(fs.existsSync(path.join(root, 'public/fonts/gensen-rounded-tw', f.file[0])), f.file[0]).toBe(true);
    }
    for (const layers of byWeight.values()) {
      expect(layers[0]).toBe('full');
      expect(layers[layers.length - 1]).toBe('-hero');
    }
  });

  it('every character the homepage renders in a weight is served by a page or hero layer, not the full file', () => {
    const chars: Record<string, string> = JSON.parse(fs.readFileSync(path.join(root, 'scripts/gensen-homepage-chars.json'), 'utf8'));
    // CSS font matching: the face the browser picks for each requested weight.
    const faceWeight: Record<number, number> = { 100: 200, 200: 200, 300: 300, 400: 400, 500: 500, 600: 700, 700: 700, 800: 900, 900: 900 };
    const uncovered: string[] = [];
    for (const [w, text] of Object.entries(chars)) {
      const own = faces.filter(f => f.weight === faceWeight[Number(w)]);
      const full = own.find(f => !f.file[2])!;
      const layers = own.filter(f => f.file[2]);
      for (const c of text) {
        const cp = c.codePointAt(0)!;
        if (!inRange(full.range!, cp)) continue; // not in GenSen at all → Noto Sans TC
        if (!layers.some(l => inRange(l.range!, cp))) uncovered.push(`${w}:${c}`);
      }
    }
    expect(uncovered).toEqual([]);
  });
});
